/// transcode unsupported video streams to H.264 for FLV/RTMP publishing.
/// <h2>Basic Usage</h2>
/// \code
/// let streamer = LiveStreamer()
/// streamer.configure(inputURL: "rtsp://camera/live", outputURL: "rtmp://server/live/stream", config: .defaultConfig())
/// streamer.startStreaming()
///
/// \endcode<h2>Objective-C Usage</h2>
/// \code
/// AIBudsLiveStreamer *streamer = [[AIBudsLiveStreamer alloc] init];
/// [streamer configureWithInputURL:@"rtsp://camera/live" outputURL:@"rtmp://server/live/stream" config:[AIBudsLiveStreamerConfig defaultConfig]];
